head.script:

	scwin.onpageload = function() {
		grd_test.options.rowNumBackgroundColor =""
	};
	scwin.onpageunload = function() {

	};


	scwin.gridView1_oncelldblclick = function(row,col,colId) {
		dataList1.removeRow(row);
	};

	scwin.gridView1_oncellclick = function(row,col,colId) {

	};

    scwin.fireOver = function(node){            
        if( document.createEventObject ) {
            node.fireEvent('onmouseover') ;  
        } else if( document.createEvent ) {
            var evt = document.createEvent('MouseEvents');
            evt.initEvent('mouseover', true, false);
            node.dispatchEvent(evt);    
        } 
        else if (typeof node.onmouseover == 'function' ) {
            node.onmouseover();           
        }
    };


    scwin.mouseOverBehaviour = function(id){
        var el = WebSquare.wUnit.getDomById(id);
        scwin.fireOver(el);
    };


    scwin.checkVal = function(){
		//alert(document.getElementById('_headerRowStatus_bodyRow_0').style.backgroundColor != 'rgb(255, 0, 128)')
		return WebSquare.wUnit.getDomById('grd_test_headerRowStatus_bodyRow_0').style.backgroundColor != 'rgb(255, 0, 128)';
    };

    scwin.unitTest = function(){
            //Unit test
            WebSquare.wUnit.start();

            WebSquare.wUnit.addCommand("pause", "500");
            WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('grd_test_cell_0_0')");
            WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_test_scrollY_div').scrollTop = 60");
            WebSquare.wUnit.addCommand("pause", "500");
            WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
            WebSquare.wUnit.addCommand("pause", "500");

            //Run and Stop test
            WebSquare.wUnit.run();
            WebSquare.wUnit.stop();
        }
        scwin.unitTest();
